function fitMap(){if(!map)return;if(!stops.length)map.setView([40.631,14.52],11);else if(stops.length===1)map.setView([stops[0].gps.lat,stops[0].gps.lng],14);else map.fitBounds(stops.map(s=>[s.gps.lat,s.gps.lng]),{paddingTopLeft:[48,90],paddingBottomRight:[48,75],maxZoom:14});}
function renderMapMarkers(){if(!mapLayers)return;mapLayers.clearLayers();markers=[];if(stops.length>1){L.polyline(stops.map(s=>[s.gps.lat,s.gps.lng]),{color:'#fff',weight:7,opacity:.95}).addTo(mapLayers);L.polyline(stops.map(s=>[s.gps.lat,s.gps.lng]),{color:'#527c5a',weight:2.5,dashArray:'5,8',opacity:.9}).addTo(mapLayers)}const placed=[];stops.forEach((s,i)=>{const actual=map.latLngToLayerPoint([s.gps.lat,s.gps.lng]);let offset=0;for(const candidate of [0,-76,76,-145,145]){const box={x:actual.x,y:actual.y+candidate};if(!placed.some(prev=>Math.abs(prev.x-box.x)<68&&Math.abs(prev.y-box.y)<85)){offset=candidate;break;}}placed.push({x:actual.x,y:actual.y+offset});if(offset){const endpoint=map.layerPointToLatLng([actual.x,actual.y+offset]);L.polyline([[s.gps.lat,s.gps.lng],endpoint],{color:'#7d9878',weight:1.3,dashArray:'2,3',opacity:.8}).addTo(mapLayers);L.circleMarker([s.gps.lat,s.gps.lng],{radius:3,color:'#fff',weight:1,fillColor:'#5d8154',fillOpacity:1}).addTo(mapLayers);}const p=s.photos[0],type=i===0?'START':i===stops.length-1?'FINISH':'';const html=`<div class="pin-wrap"><div class="photo-pin"><img src="${esc(p.src)}" alt=""><span class="pin-badge">${s.photos.length}</span></div><span class="pin-label">${type?`<span class="pin-type">${type}</span>`:''}${esc(s.name)}</span></div>`;const marker=L.marker([s.gps.lat,s.gps.lng],{icon:L.divIcon({className:'route-marker'+(s.id===selectedId?' selected':''),html,iconSize:[62,82],iconAnchor:[31,26-offset]}),title:`${type?type+' · ':''}${s.name} · ${count(s.photos.length,'photo')} · ${s.notes.length?'has notes':'add a note'}`,keyboard:true}).addTo(mapLayers).on('click',()=>openStop(s.id));if(showMapNotes&&s.notes.length)marker.bindTooltip(esc(s.notes[0].slice(0,78))+(s.notes[0].length>78?'…':''),{permanent:s.id===selectedId,direction:'top',offset:[0,-48+offset],className:'note-tooltip'});markers.push(marker)});}
function openStop(id){const s=stops.find(s=>s.id===id);if(!s)return;selectedId=id;renderMapMarkers();const d=$('#stop-sheet');const i=stops.indexOf(s);d.setAttribute('aria-label',`${s.name} photos and notes`);d.innerHTML=`<div class="sheet-scroll"><div class="sheet-hero"><img src="${esc(s.photos[0].src)}" alt="${esc(s.name)}"><span class="sheet-grabber"></span><button class="sheet-close icon-button glass" data-action="close-stop" aria-label="Close stop details">${icon('close')}</button><div class="sheet-hero-bottom"><div><span class="eyebrow">${startEnd(i)} · ${date(s.takenAt)}</span><h2>${esc(s.name)}</h2></div><span class="photo-count glass">${icon('photos')}${count(s.photos.length,'photo')}</span></div></div><div class="sheet-content"><div class="sheet-meta">${icon('pin')}<span>${Math.abs(s.gps.lat).toFixed(4)}° ${s.gps.lat<0?'S':'N'}, ${Math.abs(s.gps.lng).toFixed(4)}° ${s.gps.lng<0?'W':'E'}</span><span>· ${esc(s.source)}</span></div><div class="sheet-photos">${s.photos.map(p=>`<button data-action="photo" data-id="${esc(p.id)}" aria-label="View ${esc(p.caption||'photo')}" title="${esc(p.caption||'View photo')}"><img src="${esc(p.src)}" alt="${esc(p.caption||s.name)}"></button>`).join('')}${ownJourney()?`<button class="glass" data-action="add-to-stop" data-id="${esc(s.id)}" aria-label="Add a photo to this stop">${icon('upload')}</button>`:''}</div><div class="sheet-note glass"><div class="sheet-note-head"><span>A NOTE TO REMEMBER</span>${ownJourney()?`<button data-action="edit-note" data-id="${esc(s.id)}">${icon('edit')}${s.notes.length?'Edit':'Add note'}</button>`:''}</div><p>${s.notes.length?'“'+esc(s.notes.join('\n\n'))+'”':'What made this place yours?'}</p>${s.highlight?`<span class="highlight">✧ ${esc(s.highlight)}</span>`:''}</div><div class="sheet-footer"><button data-action="show-on-map" data-id="${esc(s.id)}">${icon('map')}Back to journey</button><span class="sheet-count">${i+1} / ${stops.length}</span>${i<stops.length-1?`<button data-action="stop" data-id="${esc(stops[i+1].id)}">Next stop ${icon('arrow')}</button>`:`<button data-action="stop" data-id="${esc(stops[0].id)}">Back to start ${icon('arrow')}</button>`}</div></div></div>`;if(!d.open)d.showModal();}
function modal(title,body,footer=''){if(locationMap){locationMap.remove();locationMap=null}const d=$('#editor');d.setAttribute('aria-label',title);d.innerHTML=`<div class="modal-frame"><header class="modal-header"><span class="eyebrow">ATLAS · EVERY PLACE HAS A STORY</span><button class="close" data-action="close-editor" aria-label="Close dialog">×</button></header><div class="modal-content">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</div>`;if(!d.open)d.showModal();}
function openNote(id,inDraft=false){editingDraft=inDraft;const j=activeJourney(),s=getStops(j).find(s=>s.id===id);if(!s)return;modal('Edit stop note',`<span class="eyebrow">A LITTLE MEMORY</span><h2>What stayed <em>with you?</em></h2><p class="modal-description">Keep the feeling, the favorite, or the tip you’d tell a friend.</p><form id="note-form" class="note-editor"><div class="field"><label for="stop-name">Place name</label><input id="stop-name" maxlength="80" value="${esc(s.name)}" required></div><div class="field"><label for="stop-note">Your note</label><textarea id="stop-note" rows="4" maxlength="2000" placeholder="The view. The coffee. The unexpected little detour…">${esc(s.notes.join('\n\n'))}</textarea></div><div class="field"><label for="stop-highlight">The highlight</label><input id="stop-highlight" list="highlight-options" maxlength="65" value="${esc(s.highlight)}" placeholder="e.g. My favorite view"><datalist id="highlight-options"><option>My favorite view</option><option>Best coffee</option><option>Go early</option><option>Hidden gem</option><option>Don’t miss sunset</option></datalist></div></form>`,`<button class="small-action" data-action="${inDraft?'organize-draft':'close-editor'}">Cancel</button><button class="button dark" form="note-form" type="submit">Save memory ${icon('check')}</button>`);$('#note-form').onsubmit=e=>{e.preventDefault();setStopAnnotation(j,s,{name:$('#stop-name').value.trim()||s.name,notes:[$('#stop-note').value.trim()].filter(Boolean),highlight:$('#stop-highlight').value.trim()});persist();if(inDraft)organize(true);else{$('#editor').close();render();openStop(s.id);toast('Memory saved to this stop')}};}
function organize(isDraft=false){if(isDraft){editingDraft=true;createStep=2;composerPlaces();return}editingDraft=isDraft;const j=activeJourney(),groups=getStops(j),unplaced=j.photos.filter(p=>!validGPS(p.gps));modal(isDraft?'Place your journey photos':'Organize journey photos',`${isDraft?stepper():''}<span class="eyebrow">PHOTOS → PLACES → MEMORIES</span><h2>Every photo.<br><em>In its place.</em></h2><p class="modal-description">Nearby photos become one stop. Add a note to the place, and keep the whole moment together.</p><div class="organize-summary"><span class="status-chip">${icon('pin')}${count(groups.length,'stop')}</span><span class="status-chip">${count(j.photos.length-unplaced.length,'photo')} placed</span>${unplaced.length?`<span class="status-chip warning">${unplaced.length} need a location</span>`:''}</div>${uploadMarkup()}<div class="group-radius"><label for="group-radius">Group photos within</label><select id="group-radius"><option value="50" ${j.radius===50?'selected':''}>50 meters</option><option value="150" ${j.radius===150?'selected':''}>150 meters</option><option value="500" ${j.radius===500?'selected':''}>500 meters</option></select></div>${unplaced.length?`<section class="group-box"><div class="group-title"><strong>A place is missing</strong><small>No location tag</small></div><div class="unplaced-grid">${unplaced.map(p=>`<button class="unplaced-card" data-action="locate" data-id="${esc(p.id)}"><img src="${esc(p.src)}" alt="${esc(p.caption||'Unplaced photo')}"><span>＋ Add location</span></button>`).join('')}</div></section>`:''}${groups.map(s=>`<section class="group-box"><div class="group-title"><div><strong>${esc(s.name)}</strong><br><small>${count(s.photos.length,'photo')} · ${esc(s.source)}</small></div><button class="small-action" data-action="${isDraft?'draft-note':'edit-note'}" data-id="${esc(s.id)}">${icon('edit')}${s.notes.length?'Edit note':'Add note'}</button></div><div class="group-thumbs">${s.photos.map(p=>`<button data-action="locate" data-id="${esc(p.id)}" aria-label="Edit location for ${esc(p.caption||'photo')}"><img src="${esc(p.src)}" alt="${esc(p.caption||s.name)}">${p.id===j.cover?'<span class="cover-badge">COVER</span>':''}</button>`).join('')}</div>${s.notes.length?`<p class="helper" style="margin-top:10px">“${esc(s.notes[0].slice(0,110))}${s.notes[0].length>110?'…':''}”</p>`:''}</section>`).join('')}<p class="helper">Location tags are read on your device. Photos and changes are saved locally.</p>`,`${isDraft?'<button class="small-action" data-action="create-back">← Photos</button>':'<span class="muted">Your photos stay together.</span>'}<button class="button dark" data-action="${isDraft?'create-next':'done-organize'}">${isDraft?'Add your story':'Done'} ${icon('arrow')}</button>`);bindUpload();$('#group-radius').onchange=e=>{j.radius=Number(e.target.value);if(!isDraft)render();organize(isDraft)};}
function uploadMarkup(){return `<label class="upload-zone" id="drop-zone">${icon('upload')}<span>Add your photos<small>JPG, PNG, WebP · up to 15 MB each</small></span><input type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp" multiple ${busy?'disabled':''}></label>`;}
function bindUpload(targetStop=null){const input=$('#photo-upload');if(!input)return;input.onchange=e=>loadPhotos(e.target.files,targetStop);const zone=$('#drop-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging')};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');loadPhotos(e.dataTransfer.files,targetStop)}}
async function loadPhotos(files,targetStop=null){if(busy)return;busy=true;const target=activeJourney();const input=$('#photo-upload');if(input)input.disabled=true;toast('Reading photo locations…');let added=0,rejected=0;for(const file of [...files].slice(0,40)){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){rejected++;continue}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=src});let meta={};try{meta=await window.exifr?.parse(file)||{}}catch{}const gps=validGPS({lat:meta.latitude,lng:meta.longitude})?{lat:meta.latitude,lng:meta.longitude}:null;const taken=meta.DateTimeOriginal||meta.CreateDate;let takenAt=taken instanceof Date&&!isNaN(taken)?taken.toISOString():null;target.photos.push({id:crypto.randomUUID(),src,caption:file.name,gps:gps||targetStop?.gps||null,place:!gps&&targetStop?targetStop.name:'',takenAt,source:gps?'gps':targetStop?'manual':'unlocated'});added++;}catch{rejected++;}}busy=false;persist();if(!target.cover)target.cover=target.photos[0]?.id;if(!editingDraft)render();if(editingDraft&&createStep===1)renderCreatePhotos();else organize(editingDraft);toast(`${count(added,'photo')} added${rejected?' · '+rejected+' could not be read':''}. ${target.photos.filter(p=>!validGPS(p.gps)).length?'Place photos without location tags.':'Locations are grouped into stops.'}`);}
function openLocation(id){const j=activeJourney(),p=j.photos.find(p=>p.id===id);if(!p)return;locationState={id,isDraft:editingDraft,point:p.gps?{...p.gps}:null,name:p.place||''};const groups=getStops(j);modal('Add a photo location',`<span class="eyebrow">GIVE THIS MEMORY A PLACE</span><h2>Where was <em>this?</em></h2><div class="location-target"><img src="${esc(p.src)}" alt="Photo to locate"><div><strong>${p.gps?'Fine-tune this location':'No location tag found'}</strong><small>Choose a stop, tap the map, or enter coordinates.</small></div></div><div class="location-choices">${groups.map(s=>`<button data-action="choose-place" data-id="${esc(s.id)}">${esc(s.name)}</button>`).join('')}</div><div class="location-picker"><div id="picker-map" class="picker-map"></div><span class="picker-hint glass">${icon('pin')} Tap anywhere to place the photo</span></div><div class="coordinate-label" id="coordinate-label">${p.gps?`${p.gps.lat.toFixed(5)}, ${p.gps.lng.toFixed(5)}`:'No point selected yet'}</div><form id="location-form"><div class="field"><label for="location-name">Place name</label><input id="location-name" placeholder="A café, a beach, a little discovery…" maxlength="80" value="${esc(p.place||'')}"></div><details><summary class="small-action">Enter coordinates manually</summary><div class="field-grid"><div class="field"><label for="location-lat">Latitude</label><input id="location-lat" type="number" min="-90" max="90" step="any" value="${p.gps?.lat??''}"></div><div class="field"><label for="location-lng">Longitude</label><input id="location-lng" type="number" min="-180" max="180" step="any" value="${p.gps?.lng??''}"></div></div></details></form><p class="location-info" id="location-match">${p.gps?'You can move this photo to a different stop.':'A nearby photo joins an existing stop. A new place starts a new stop.'}</p>`,`<button class="small-action" data-action="${editingDraft?'organize-draft':'organize'}">← Back</button><button class="button dark" type="submit" form="location-form">Save location ${icon('pin')}</button>`);
 if(window.L){locationMap=L.map('picker-map',{zoomControl:true,scrollWheelZoom:false}).setView(p.gps?[p.gps.lat,p.gps.lng]:[40.631,14.52],p.gps?14:11);tileLayer(locationMap);groups.forEach(s=>L.circleMarker([s.gps.lat,s.gps.lng],{radius:6,color:'#618b51',weight:2,fillColor:'#fff',fillOpacity:1}).addTo(locationMap).bindTooltip(esc(s.name)).on('click',()=>chooseLocation(s.gps,s.name)));locationMap.on('click',e=>chooseLocation({lat:e.latlng.lat,lng:e.latlng.lng},$('#location-name').value));if(p.gps)locationMarker=L.circleMarker([p.gps.lat,p.gps.lng],{radius:10,color:'#497a3e',weight:3,fillColor:'#fff',fillOpacity:.85}).addTo(locationMap);else locationMarker=null;locationMap.whenReady(()=>locationMap.invalidateSize());}
 const coordinateChange=()=>{const lat=$('#location-lat').value,lng=$('#location-lng').value;const point={lat:Number(lat),lng:Number(lng)};if(lat!==''&&lng!==''&&validGPS(point))chooseLocation(point,$('#location-name').value,false);else locationState.point=null;};$('#location-lat').oninput=coordinateChange;$('#location-lng').oninput=coordinateChange;
 $('#location-form').onsubmit=e=>{e.preventDefault();if(!validGPS(locationState.point)){toast('Choose a point on the map or enter valid coordinates.');return}const name=$('#location-name').value.trim();const nearest=groups.find(s=>distanceMeters(s.gps,locationState.point)<=j.radius);if(!name&&!nearest){toast('Give this new place a name.');$('#location-name').focus();return}const oldGroup=groups.find(g=>g.photos.some(photo=>photo.id===p.id));if(j.annotations[p.id]&&oldGroup?.photos.length>1&&distanceMeters(oldGroup.gps,locationState.point)>j.radius){const keeper=oldGroup.photos.find(photo=>photo.id!==p.id);const record=j.annotations[p.id];const other=j.annotations[keeper.id];j.annotations[keeper.id]={name:other?.name||record.name,notes:[...new Set([...(other?.notes||[]),...(record.notes||[])])],highlight:other?.highlight||record.highlight};delete j.annotations[p.id];}p.gps={...locationState.point};p.place=name||nearest.name;p.source='manual';const anchorAnnotation=j.annotations[p.id];if(anchorAnnotation&&name)anchorAnnotation.name=name;else if(!nearest&&name)j.annotations[p.id]={name,notes:[],highlight:''};locationState=null;persist();if(!editingDraft)render();organize(editingDraft);toast(nearest?'Photo added to '+nearest.name:'A new stop has been added');};
}
function chooseLocation(point,name,writeCoordinates=true){locationState.point={...point};if(name)$('#location-name').value=name;if(writeCoordinates){$('#location-lat').value=point.lat.toFixed(6);$('#location-lng').value=point.lng.toFixed(6)}$('#coordinate-label').textContent=`${point.lat.toFixed(5)}, ${point.lng.toFixed(5)}`;const nearest=getStops(activeJourney()).find(s=>distanceMeters(s.gps,point)<=activeJourney().radius);$('#location-match').textContent=nearest?`This photo will join ${nearest.name}, with ${count(nearest.photos.length,'photo')}.`:'This photo will create a new stop on your journey.';if(locationMap){if(locationMarker)locationMarker.setLatLng([point.lat,point.lng]);else locationMarker=L.circleMarker([point.lat,point.lng],{radius:10,color:'#497a3e',weight:3,fillColor:'#fff',fillOpacity:.85}).addTo(locationMap);locationMap.panTo([point.lat,point.lng]);}}
function stepper(){return `<nav class="creation-progress" aria-label="Creation progress">${['Photos','Places','Details','Preview'].map((s,i)=>`<div class="${createStep===i+1?'active':createStep>i+1?'complete':''}" ${createStep===i+1?'aria-current="step"':''}><span>${createStep>i+1?icon('check'):i+1}</span><strong>${s}</strong></div>`).join('')}</nav>`;}
function startCreate(){editingDraft=true;if(!draft){createStep=1;draft={id:crypto.randomUUID(),title:'',place:'',start:'',end:'',caption:'',cover:null,photos:[],annotations:{},radius:150,audience:'private',category:'Coast'};}if(createStep===4&&draft.title)createPreview();else if(createStep===3)createStory();else if(createStep===2&&draft.photos.length)composerPlaces();else renderCreatePhotos();}
function renderCreatePhotos(){editingDraft=true;createStep=1;composerLayout('Every journey starts<br>with <em>a moment.</em>','Choose the photos you want to remember. We’ll connect the places.',createPhotoBody(),`<button class="text-link" data-action="save-draft">Save & leave</button><button class="button dark" data-action="create-next" ${!draft.photos.length?'disabled':''}>Find the places ${icon('arrow')}</button>`);bindUpload();}
function createStory(){editingDraft=true;createStep=3;composerLayout('Make it <em>yours.</em>','The title. The feeling. The photo that says it all.',`<div class="details-layout"><form id="story-form"><div class="field"><label for="journey-title">Give your journey a name</label><input id="journey-title" placeholder="A little closer to la dolce vita" maxlength="100" required value="${esc(draft.title)}"></div><div class="field"><label for="journey-place">Where did you go?</label><input id="journey-place" placeholder="Amalfi Coast, Italy" maxlength="100" required value="${esc(draft.place)}"></div><div class="field-grid"><div class="field"><label for="journey-start">First day</label><input id="journey-start" type="date" value="${esc(draft.start)}" required></div><div class="field"><label for="journey-end">Last day</label><input id="journey-end" type="date" value="${esc(draft.end)}" required></div></div><div class="field"><label for="journey-caption">What will you remember? <span>Optional</span></label><textarea id="journey-caption" maxlength="1200" rows="4" placeholder="The feeling you wish you could bottle…">${esc(draft.caption)}</textarea></div><div class="field"><label for="journey-category">Your kind of trip</label><select id="journey-category">${['Coast','Mountains','City'].map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></div></form><section class="cover-picking"><div class="section-heading"><h2>The first <em>impression.</em></h2><span>Choose a cover</span></div><div class="cover-preview"><img id="chosen-cover-preview" src="${coverPhoto(draft).src}" alt="Selected journey cover"><span class="glass">${icon('photos')}Your cover</span></div><div class="cover-select">${draft.photos.map(p=>`<button type="button" data-action="choose-cover" data-id="${p.id}" aria-label="Use ${esc(p.caption||'photo')} as cover" aria-pressed="${draft.cover===p.id}" class="${draft.cover===p.id?'chosen':''}"><img src="${p.src}" alt="${esc(p.caption||'Cover choice')}"></button>`).join('')}</div></section></div>`,`<button class="text-link" data-action="create-back">${icon('back')}Places</button><button class="button dark" type="submit" form="story-form">Preview journey ${icon('arrow')}</button>`);$('#story-form').oninput=()=>{collectStory();persist()};$('#story-form').onsubmit=e=>{e.preventDefault();collectStory();if(!draft.title||!draft.place){toast('Give your journey a title and a destination.');return}if(draft.end<draft.start){toast('The last day must be on or after the first day.');return}createStep=4;createPreview();window.scrollTo(0,0);};}
function collectStory(){if(!$('#story-form')||!draft)return;draft.title=$('#journey-title').value.trim();draft.place=$('#journey-place').value.trim();draft.start=$('#journey-start').value;draft.end=$('#journey-end').value;draft.caption=$('#journey-caption').value.trim();draft.category=$('#journey-category')?.value||'Coast';}
function createPreview(){editingDraft=true;createStep=4;const groups=getStops(draft),missing=draft.photos.filter(p=>!validGPS(p.gps));composerLayout('Ready to <em>keep forever.</em>','One last look before this becomes part of your world.',`<div class="preview-layout"><section><div class="review-photo"><img src="${coverPhoto(draft).src}" alt="Journey cover"><div><span>${esc(draft.place)} · ${dayCount(draft)} days</span><h3>${esc(draft.title)}</h3><span>${count(draft.photos.length,'photo')} · ${count(groups.length,'stop')}</span></div></div>${draft.caption?`<p class="preview-caption">“${esc(draft.caption)}”</p>`:''}<div class="preview-route">${groups.map((s,i)=>`<div><span class="preview-route-dot">${i+1}</span><img src="${s.photos[0].src}" alt="${esc(s.name)}"><span><strong>${esc(s.name)}</strong><small>${count(s.photos.length,'photo')} · ${s.highlight?esc(s.highlight):s.notes.length?'A memory added':'A place to remember'}</small></span></div>`).join('')}</div></section><section class="audience-panel glass"><span class="eyebrow">YOUR JOURNEY, YOUR CHOICE</span><h2>Who’s coming <em>along?</em></h2><p>Choose the audience for this journey.</p><fieldset class="audience-options"><legend class="sr-only">Journey audience</legend>${[['private','lock','Only me','A personal keepsake, just for you.'],['followers','people','Followers','The people who follow your travels.'],['everyone','globe','Everyone','A little inspiration for the world.']].map(([v,ic,t,d])=>`<label class="audience-choice"><input type="radio" name="audience" value="${v}" ${draft.audience===v?'checked':''}>${icon(ic)}<span><strong>${t}</strong><small>${d}</small></span><i></i></label>`).join('')}</fieldset>${missing.length?`<div class="missing-review">${icon('pin')}<span>${count(missing.length,'photo')} without a place will stay in the album.<button class="text-link" data-action="review-places">Add locations</button></span></div>`:''}<div class="publish-note">${icon('lock')}<p>In this preview, posting saves to this device. Audience settings are a design preview; nothing is shared online.</p></div></section></div>`,`<button class="text-link" data-action="create-back">${icon('back')}Details</button><button class="button dark" data-action="post">Post journey ${icon('arrow')}</button>`);$$('input[name="audience"]').forEach(el=>el.onchange=()=>{draft.audience=el.value;persist()});}
function nextCreate(){if(createStep===1){if(!draft.photos.length)return;draft.cover||=draft.photos[0].id;const known=draft.photos.map(p=>p.takenAt).filter(Boolean).sort();if(known.length){draft.start||=known[0].slice(0,10);draft.end||=known.at(-1).slice(0,10)}if(draft.photos.some(p=>p.source==='sample'))draft.place||='Amalfi Coast, Italy';createStep=2;organize(true)}else if(createStep===2)createStory();persist();window.scrollTo(0,0);}
function showCollection(onlySaved=false){go(onlySaved?'saved':'profile');}
function showGallery(){modal('Journey photo album',`<span class="eyebrow">EVERY MOMENT, KEPT</span><h2>Your <em>camera roll.</em></h2><p class="modal-description">${count(journey.photos.length,'photo')} from ${esc(journey.place)}.</p><div class="full-gallery">${journey.photos.map(p=>{const s=stops.find(s=>s.photos.some(sp=>sp.id===p.id));return `<button data-action="photo" data-id="${esc(p.id)}"><img src="${esc(p.src)}" alt="${esc(p.caption||'Journey photo')}"><span>${s?esc(s.name):'＋ Add location'}</span></button>`}).join('')}</div>`,`<span class="muted">Your moments, connected.</span>${ownJourney()?'<button class="button" data-action="organize">Organize photos</button>':''}`);}
function openPhoto(id){const group=stops.find(s=>s.photos.some(p=>p.id===id));lightboxIds=(group?group.photos:journey.photos).map(p=>p.id);lightboxIndex=lightboxIds.indexOf(id);renderLightbox();}
function renderLightbox(){const p=journey.photos.find(p=>p.id===lightboxIds[lightboxIndex]);if(!p)return;const s=stops.find(s=>s.photos.some(sp=>sp.id===p.id)),d=$('#lightbox');d.innerHTML=`<div class="lightbox-header"><span>${s?esc(s.name):'A memory waiting for a place'} · ${lightboxIndex+1} / ${lightboxIds.length}</span><button class="close" data-action="close-lightbox" aria-label="Close photo">×</button></div><img src="${esc(p.src)}" alt="${esc(p.caption||'Journey photo')}"><div class="lightbox-footer"><button data-action="photo-prev" ${lightboxIndex===0?'disabled':''}>${icon('back')}Previous</button>${ownJourney()?`<button data-action="photo-location" data-id="${esc(p.id)}">${icon('pin')}${p.gps?'Edit location':'Add location'}</button>`:''}<button data-action="photo-next" ${lightboxIndex===lightboxIds.length-1?'disabled':''}>Next ${icon('arrow')}</button></div>`;if(!d.open)d.showModal();}
function share(){const c=coverPhoto(journey);modal('Share journey',`<span class="eyebrow">SEND A LITTLE INSPIRATION</span><h2>Better <em>together.</em></h2><div class="collection-card"><img src="${esc(c.src)}" alt="${esc(journey.place)}"><div><h3>${esc(journey.title)}</h3><p>${esc(journey.place)} · ${count(stops.length,'stop')}</p></div></div><p class="modal-description">Copy a link to this journey in your local preview.</p><p class="helper">This link needs the local app running. Your own journeys are stored in this browser, so they aren’t available to other people yet.</p>`,`<span class="muted">Local preview link</span><button class="button dark" data-action="copy-link">Copy link ${icon('share')}</button>`);}
function changeView(next){view=next;render();$('.journey-canvas').scrollIntoView({block:'center',behavior:'smooth'});}
function closeEditor(){if(editingDraft&&$('#story-form'))collectStory();persist();$('#editor').close();if(locationMap){locationMap.remove();locationMap=null}locationState=null;editingDraft=screen==='create';}
function allJourneys(){return [...journeys,sampleState,...communityJourneys];}
function findJourney(id){return allJourneys().find(j=>j.id===id);}
function ownJourney(j=journey){return !j.author||j.author==='me';}
function person(id='me'){return id==='me'?profile:people[id]||profile;}
function dayCount(j){return Math.max(1,Math.round((Date.parse(j.end)-Date.parse(j.start))/86400000)+1)||1;}
function avatar(p,extra=''){return `<span class="person-avatar ${p.color||'sage'} ${extra}" aria-hidden="true">${esc(p.initials||p.name.slice(0,2))}</span>`;}
function snapshot(){return {version:1,journeys,sampleState,draft,createStep,profile,savedIds:[...savedIds],likedIds:[...likedIds],following:[...following],comments};}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(flushState,180);}
async function flushState(){clearTimeout(saveTimer);try{await writeState(snapshot());$$('.autosave-label').forEach(e=>e.textContent='Saved on this device');}catch{if(!storageWarned){storageWarned=true;toast('Device storage is unavailable. Keep this tab open to retain your changes.');}}}
function routeFromHash(){const [page,id]=location.hash.replace(/^#\/?/,'').split('/');return {page:['home','explore','saved','profile','journey','create'].includes(page)?page:'home',id:id?decodeURIComponent(id):null};}
function go(page,id){if(editingDraft&&$('#story-form'))collectStory();persist();closeEditor();$('#stop-sheet').close();$('#lightbox').close();if(screen!=='journey'&&page==='journey')returnScreen=screen;history.pushState({},'',`#/${page}${id?'/'+encodeURIComponent(id):''}`);renderScreen();window.scrollTo({top:0,behavior:'instant'});}
function renderScreen(){const r=routeFromHash();screen=r.page;document.body.dataset.screen=screen;renderShell(screen);if(screen==='journey'){const j=findJourney(r.id);if(!j){go('home');toast('This journey is not available on this device.');return}journey=structuredClone(j);render();}else if(screen==='home')renderHome();else if(screen==='explore')renderExplore();else if(screen==='saved')renderSaved();else if(screen==='profile')renderProfile(r.id||'me');else startCreate();}
function renderShell(active){const tabs=[['home','home','Home'],['explore','compass','Explore'],['saved','save','Saved'],['profile','person','Your world']];$('.site-nav').innerHTML=`<a class="brand" href="#/home" data-action="nav" data-id="home"><span class="brand-icon">⌁</span>atlas<span>.</span></a><nav class="desktop-nav glass" aria-label="Main navigation">${tabs.map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="nav-actions"><span class="prototype-tag">LOCAL PREVIEW</span><button class="button dark nav-create" data-action="create">${icon('plus')}<span>New journey</span></button><button class="profile-nav" data-action="nav" data-id="profile" aria-label="Your profile">${avatar(profile)}</button></div>`;$('.mobile-dock').setAttribute('aria-label','Main navigation');$('.mobile-dock').innerHTML=`${tabs.slice(0,2).map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}<button class="dock-create" data-action="create" aria-label="Create a new journey">${icon('plus')}</button>${tabs.slice(2).map(([id,ic,label])=>`<button data-action="nav" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${id==='profile'?'You':label}</span></button>`).join('')}`;$('.mobile-dock').hidden=active==='create';}
function pageMain(html,cls='app-page'){$('#journey').className=cls;$('#journey').innerHTML=html;}
function categoryChips(action,current){return `<div class="category-chips" aria-label="Journey categories">${['All','Coast','Mountains','City'].map(c=>`<button class="${current===c?'selected':''}" data-action="${action}" data-id="${c}" aria-pressed="${current===c}">${c==='All'?icon('sparkle'):c==='Coast'?icon('sun'):c==='Mountains'?icon('mountain'):icon('city')}${c==='All'?'All journeys':c}</button>`).join('')}</div>`;}
function routeRibbon(j){const ss=getStops(j),chosen=ss.length>3?[ss[0],ss[Math.floor(ss.length/2)],ss.at(-1)]:ss;return `<div class="route-ribbon" aria-label="Journey stops"><div class="ribbon-line"></div>${chosen.map((s,i)=>`<span><i class="${i===chosen.length-1?'last':''}"></i><small>${esc(s.name)}</small></span>`).join('')}${!ss.length?'<small>Memories waiting for a place</small>':''}</div>`;}
function journeyCard(j,compact=false){const p=person(j.author),saved=savedIds.has(j.id),liked=likedIds.has(j.id),ss=getStops(j),c=coverPhoto(j);return `<article class="feed-card ${compact?'compact-card':''}"><div class="feed-author"><button data-action="author" data-id="${p.id}" class="author-link">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(j.place)} ${ownJourney(j)?'· Your journey':''}</small></span></button>${j.demo?'<span class="demo-badge">Demo trip</span>':`<span class="feed-date">${date(j.start)}</span>`}</div><div class="feed-image"><button class="open-feed-image" data-action="open-journey" data-id="${esc(j.id)}" aria-label="Open ${esc(j.title)}"><img src="${esc(c?.src||media.positano)}" alt="${esc(c?.caption||j.place)}" loading="lazy"><span class="feed-image-shade"></span><span class="feed-image-text"><span class="eyebrow">${esc(j.place.split(',').at(-1).trim())} <i>·</i> ${dayCount(j)} DAYS</span><strong>${esc(j.title)}</strong></span></button><span class="trip-kind glass">${icon(j.category==='Mountains'?'mountain':j.category==='City'?'city':'sun')}${esc(j.category||'A little escape')}</span><button class="image-save glass ${saved?'is-saved':''}" data-action="toggle-save" data-id="${esc(j.id)}" aria-label="${saved?'Unsave':'Save'} ${esc(j.title)}" aria-pressed="${saved}">${icon('save')}</button><span class="image-count glass">${icon('photos')}${j.photos.length}</span></div>${routeRibbon(j)}${compact?'':`<div class="feed-insight"><span>${icon('note')}</span><p>${esc(ss.find(s=>s.notes.length)?.notes[0]||j.caption||'A few places. A thousand little memories.')}</p></div>`}<div class="feed-card-footer"><div><button class="reaction ${liked?'liked':''}" data-action="like" data-id="${esc(j.id)}" aria-label="${liked?'Unlike':'Like'} ${esc(j.title)}" aria-pressed="${liked}">${icon('heart')}<span>${liked?'Loved':'Love this'}</span></button><button class="reaction comment-action" data-action="comments" data-id="${esc(j.id)}" aria-label="Open comments on ${esc(j.title)}">${icon('chat')}<span>${comments[j.id]?.length||''}</span></button></div><button class="read-journey" data-action="open-journey" data-id="${esc(j.id)}">Explore ${ss.length} stops ${icon('arrow')}</button></div></article>`;}
function draftNudge(){return `<button class="draft-nudge glass" data-action="create"><span class="draft-icon">${icon(draft?.photos.length?'edit':'photos')}</span><span><strong>${draft?.photos.length?'A little story, still unfolding.':'Your camera roll has a story.'}</strong><small>${draft?.photos.length?`${count(draft.photos.length,'photo')} · Continue your draft`:'Turn your favorite trip into a journey.'}</small></span>${icon('arrow')}</button>`;}
function renderHome(){const filtered=allJourneys().filter(j=>(feedTab!=='following'||following.has(j.author))&&(feedCategory==='All'||j.category===feedCategory));pageMain(`<div class="home-intro"><div><span class="eyebrow">A WORLD WORTH WANDERING</span><h1>A little inspiration.<br><em>A world of possibilities.</em></h1><p>Good places. Real memories. Your next story.</p></div><button class="intro-create button glass" data-action="create">${icon('plus')}Tell your story</button></div><div class="app-columns"><section class="feed-column">${draftNudge()}<div class="feed-switch"><div role="group" aria-label="Feed"><button class="${feedTab==='all'?'active':''}" data-action="feed-tab" data-id="all" aria-pressed="${feedTab==='all'}">For you</button><button class="${feedTab==='following'?'active':''}" data-action="feed-tab" data-id="following" aria-pressed="${feedTab==='following'}">Following</button></div><span>Little journeys, big feelings</span></div>${categoryChips('feed-category',feedCategory)}<div class="feed-list">${filtered.map(j=>journeyCard(j)).join('')||emptyState('A quieter corner of the world.','Follow a traveler to see their journeys here.','Discover people','explore')}</div><div class="feed-end">${icon('sparkle')}You’re all caught up. Go make a little memory.</div></section><aside class="home-aside"><section class="side-card glass"><div class="section-heading"><h2>Your little <em>world.</em></h2>${icon('route')}</div><p>Every trip adds something to your story.</p><div class="mini-stats"><span><b>${journeys.length+1}</b>journeys</span><span><b>${[...journeys,sampleState].reduce((a,j)=>a+getStops(j).length,0)}</b>places</span><span><b>${savedIds.size}</b>saved</span></div><button class="text-link" data-action="nav" data-id="profile">Visit your world ${icon('arrow')}</button></section><section class="side-card"><span class="eyebrow">PEOPLE WITH A DIFFERENT PERSPECTIVE</span><h2>Follow a little <em>curiosity.</em></h2>${Object.values(people).filter(p=>p.id!=='me').map(p=>`<div class="suggested-person"><button class="author-link" data-action="author" data-id="${p.id}">${avatar(p)}<span><strong>${p.name}</strong><small>${p.location}</small></span></button><button class="follow-small glass" data-action="follow" data-id="${p.id}" aria-label="${following.has(p.id)?'Unfollow':'Follow'} ${p.name}">${following.has(p.id)?icon('check'):icon('plus')}</button></div>`).join('')}<small class="demo-note">Illustrative traveler profiles</small></section><button class="side-destination" data-action="search-destination" data-id="Switzerland"><img src="${travelImages.alps}" alt="A lake surrounded by mountains"><span><small>TAKE THE SCENIC ROUTE</small><strong>Somewhere<br><em>a little slower.</em></strong>${icon('arrow')}</span></button></aside></div>`);}
function emptyState(title,body,label,page){return `<div class="app-empty glass">${icon('compass')}<h2>${title}</h2><p>${body}</p><button class="button dark" data-action="nav" data-id="${page}">${label} ${icon('arrow')}</button></div>`;}
function renderExplore(){pageMain(`<header class="page-intro"><span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h1>Where to <em>next?</em></h1><p>Find a place. Fall for someone’s journey.</p></header><label class="explore-search glass">${icon('search')}<input id="explore-search" type="search" placeholder="A place, a feeling, a little escape…" value="${esc(searchQuery)}" aria-label="Search journeys"><span>Explore</span></label><div class="destination-grid">${[{label:'By the sea',place:'Italy',src:media.positano},{label:'Into the quiet',place:'Switzerland',src:travelImages.alps},{label:'A different rhythm',place:'Japan',src:travelImages.japan}].map(d=>`<button data-action="search-destination" data-id="${d.place}" class="destination-tile"><img src="${d.src}" alt="${d.place}"><span><small>${d.label}</small><strong>${d.place}</strong></span></button>`).join('')}</div><div class="section-heading explore-heading"><div><span class="eyebrow">TRIPS TO KEEP CLOSE</span><h2>Find your kind of <em>away.</em></h2></div><span class="demo-note">Curated demo journeys</span></div>${categoryChips('explore-category',exploreCategory)}<div id="explore-results" class="explore-results"></div>`);renderSearchResults();$('#explore-search').oninput=e=>{searchQuery=e.target.value;renderSearchResults()};}
function renderSearchResults(){const q=searchQuery.trim().toLowerCase(),list=allJourneys().filter(j=>(exploreCategory==='All'||j.category===exploreCategory)&&`${j.title} ${j.place} ${j.category} ${j.caption} ${getStops(j).map(s=>s.name+' '+s.notes.join(' ')).join(' ')}`.toLowerCase().includes(q));$('#explore-results').innerHTML=list.map(j=>journeyCard(j,true)).join('')||emptyState('Somewhere else is waiting.','Try a country, a place name, or a different kind of trip.','See all journeys','explore');}
function renderSaved(){const list=allJourneys().filter(j=>savedIds.has(j.id));pageMain(`<header class="page-intro"><span class="eyebrow">FOR A FUTURE YOU</span><h1>A little shelf<br>of <em>someday.</em></h1><p>${list.length?`${count(list.length,'journey')} to come back to. No need to remember every name.`:'Keep the journeys that make you want to pack a bag.'}</p></header>${list.length?`<div class="saved-banner glass">${icon('save')}<span>Good places deserve a second look.</span><button class="text-link" data-action="nav" data-id="explore">Find more ${icon('arrow')}</button></div><div class="explore-results">${list.map(j=>journeyCard(j,true)).join('')}</div>`:emptyState('Your next trip might start here.','Tap the bookmark on any journey. Its route, photos, and tips will be waiting for you.','Explore journeys','explore')}`);}
function renderProfile(id='me'){const p=person(id),mine=id==='me',list=allJourneys().filter(j=>(j.author||'me')===id),photos=list.flatMap(j=>j.photos),places=list.reduce((a,j)=>a+getStops(j).length,0),countries=[...new Set(list.map(j=>j.place.split(',').at(-1).trim()))];pageMain(`<section class="profile-cover"><img src="${coverPhoto(list[0]||sampleState).src}" alt="${esc(list[0]?.place||'Travel memories')}"><div class="profile-cover-shade"></div><span class="profile-cover-label glass">${icon('route')}A life in little journeys</span>${mine?'<button class="icon-button glass profile-settings" data-action="settings" aria-label="Profile settings">'+icon('settings')+'</button>':''}</section><section class="profile-summary">${avatar(p,'profile-avatar')}<div class="profile-title"><div><span class="eyebrow">@${esc(p.handle)}</span><h1>${esc(p.name)}</h1></div>${mine?'<button class="button glass" data-action="edit-profile">'+icon('edit')+' Edit profile</button>':`<button class="button ${following.has(id)?'glass':'dark'}" data-action="follow" data-id="${id}">${following.has(id)?'Following':'Follow journey'} ${icon(following.has(id)?'check':'plus')}</button>`}</div><p class="profile-bio">${esc(p.bio)}</p><span class="profile-location">${icon('pin')}${esc(p.location)} ${mine?'':'<i>· Demo profile</i>'}</span><div class="profile-stats"><span><strong>${list.length}</strong>journeys</span><span><strong>${places}</strong>places</span><span><strong>${photos.length}</strong>memories</span>${mine?`<button data-action="following-list"><strong>${following.size}</strong>following</button>`:''}</div></section><div class="profile-content"><section class="passport glass"><div><span class="eyebrow">YOUR TRAVEL SHELF</span><h2>${countries.length?'A little more of the':'So much of the'} <em>world.</em></h2></div><div class="passport-stamps">${countries.map(c=>`<span class="passport-stamp">${icon('sun')}<strong>${esc(c)}</strong><small>A MOMENT KEPT</small></span>`).join('')||'<p>Your first stamp is waiting.</p>'}</div></section><div class="profile-tabs" role="group" aria-label="Profile sections">${['journeys','photos',...(mine?['drafts']:[])].map(t=>`<button class="${profileTab===t?'active':''}" data-action="profile-tab" data-id="${t}" data-person="${id}" aria-pressed="${profileTab===t}">${t==='journeys'?'Journeys':t==='photos'?'Camera roll':'Drafts'}${t==='drafts'&&draft?.photos.length?'<i>1</i>':''}</button>`).join('')}</div>${profileTab==='drafts'&&mine?`<div class="drafts-page">${draft?.photos.length?draftNudge():emptyState('No unfinished adventures.','Start with a few photos. We’ll keep your place while you find the words.','Start a journey','create')}</div>`:profileTab==='photos'?`<div class="profile-photo-grid">${list.flatMap(j=>j.photos.map(p=>`<button data-action="profile-photo" data-id="${p.id}" data-journey="${j.id}" aria-label="View ${esc(p.caption)}"><img src="${p.src}" alt="${esc(p.caption)}" loading="lazy"></button>`)).join('')}</div>`:`<div class="profile-journeys">${list.map(j=>journeyCard(j,true)).join('')}${mine?'<button class="new-trip-card glass" data-action="create">'+icon('plus')+'<strong>Your next chapter</strong><span>Every journey starts with a moment.</span></button>':''}</div>`}</div>`,'app-page profile-page');}
function editProfile(){modal('Edit your profile',`<span class="eyebrow">YOUR LITTLE CORNER</span><h2>A little more <em>you.</em></h2><form id="profile-form"><div class="field"><label for="profile-name">Your name</label><input id="profile-name" maxlength="50" required value="${esc(profile.name)}"></div><div class="field"><label for="profile-handle">Username</label><input id="profile-handle" pattern="[A-Za-z0-9_]{3,24}" title="3–24 letters, numbers, or underscores" required value="${esc(profile.handle)}"></div><div class="field"><label for="profile-bio">A few words about you</label><textarea id="profile-bio" rows="3" maxlength="180">${esc(profile.bio)}</textarea></div><div class="field"><label for="profile-location">Home base</label><input id="profile-location" maxlength="80" value="${esc(profile.location)}"></div></form>`,`<button class="small-action" data-action="close-editor">Cancel</button><button class="button dark" form="profile-form" type="submit">Save profile ${icon('check')}</button>`);$('#profile-form').onsubmit=e=>{e.preventDefault();const name=$('#profile-name').value.trim();if(!name)return;profile={...profile,name,handle:$('#profile-handle').value.trim(),bio:$('#profile-bio').value.trim(),location:$('#profile-location').value.trim(),initials:name.split(/\s+/).slice(0,2).map(s=>s[0]).join('')};closeEditor();persist();renderShell('profile');renderProfile();toast('Your profile is updated.');};}
function showComments(id){const j=findJourney(id);if(!j)return;const items=comments[id]||[];modal('Journey conversation',`<span class="eyebrow">A LITTLE CONVERSATION</span><h2>Ask. Share. <em>Connect.</em></h2><p class="modal-description">${esc(j.title)}</p><div class="comments-list">${items.map(c=>`<article class="comment">${avatar(profile)}<div><strong>${esc(profile.name)}<small>Only on this device</small></strong><p>${esc(c.text)}</p></div></article>`).join('')||'<p class="comment-empty">What caught your eye? Leave a thought or a question.</p>'}</div><form id="comment-form"><label class="sr-only" for="comment-text">Your comment</label><textarea id="comment-text" maxlength="1000" placeholder="That little place you want to know more about…" rows="3" required></textarea></form><p class="helper">Preview conversation. Comments are saved locally and aren’t sent to other people.</p>`,`<button class="small-action" data-action="close-editor">Close</button><button class="button dark" type="submit" form="comment-form">Add comment ${icon('arrow')}</button>`);$('#comment-form').onsubmit=e=>{e.preventDefault();const text=$('#comment-text').value.trim();if(!text)return;(comments[id]??=[]).push({text,createdAt:new Date().toISOString()});persist();showComments(id);};}
function showFollowing(){modal('People you follow',`<span class="eyebrow">FELLOW WANDERERS</span><h2>A little shared <em>curiosity.</em></h2>${Object.values(people).filter(p=>p.id!=='me').map(p=>`<div class="suggested-person"><button class="author-link" data-action="author" data-id="${p.id}">${avatar(p)}<span><strong>${p.name}</strong><small>${p.location}</small></span></button><button class="button glass" data-action="follow" data-id="${p.id}">${following.has(p.id)?'Following':'Follow'}</button></div>`).join('')}<p class="helper">Illustrative profiles. Following is saved on this device.</p>`,`<span class="muted">${following.size} following</span><button class="button dark" data-action="close-editor">Done</button>`);}
function composerLayout(title,subtitle,body,footer){screen='create';document.body.dataset.screen='create';renderShell('create');if($('#editor').open)$('#editor').close();pageMain(`<div class="composer-top"><button class="text-link" data-action="save-draft">${icon('back')}Back to your world</button><span class="autosave-label">Saved on this device</span></div>${stepper()}<header class="composer-title"><span class="eyebrow">A NEW CHAPTER · STEP ${createStep} OF 4</span><h1>${title}</h1><p>${subtitle}</p></header><div class="composer-body">${body}</div><footer class="composer-bottom glass">${footer}</footer>`,'app-page composer-page');persist();}
function createPhotoBody(){return `${uploadMarkup()}${draft.photos.length?`<div class="selection-heading"><h2>${count(draft.photos.length,'moment')}, <em>chosen.</em></h2><small>Tap × to remove a photo</small></div><div class="selected-photos">${draft.photos.map((p,i)=>`<div class="selected-photo"><img src="${esc(p.src)}" alt="${esc(p.caption||'Selected photo')}"><span class="selected-number glass">${i+1}</span><button class="remove-photo glass" data-action="remove-draft-photo" data-id="${esc(p.id)}" aria-label="Remove ${esc(p.caption||'photo')}">${icon('close')}</button><span class="photo-location-status glass">${icon(p.gps?'pin':'plus')}${p.gps?'Location found':'Add place later'}</span></div>`).join('')}</div>`:`<div class="photo-promise"><div class="promise-photos"><img src="${media.sorrento}" alt="Coastal travel memory"><img src="${media.positano}" alt="A favorite view"><img src="${media.food}" alt="A memorable meal"></div><h2>They’re more than <em>photos.</em></h2><p>They’re the places, the people, the little things.<br>Let’s put them back together.</p></div>`}<div class="sample-picker glass"><div>${icon('sparkle')}<span><strong>Just looking around?</strong><small>Try the full flow with our Amalfi sample trip.</small></span></div><button class="button" data-action="use-demo">Use sample photos ${icon('arrow')}</button></div><p class="composer-helper">${icon('lock')}Your photos stay on this device. Location tags help connect the stops.</p>`;}
function composerPlaces(){const groups=getStops(draft),unplaced=draft.photos.filter(p=>!validGPS(p.gps));composerLayout('A place for <em>every moment.</em>','We’ve brought nearby photos together. Make each stop yours.',`<div class="places-summary glass"><span>${icon('check')}<b>${groups.length}</b> stops found</span><span>${icon('photos')}${draft.photos.length} photos</span>${unplaced.length?`<span class="needs-place">${unplaced.length} need a place</span>`:''}</div><div class="group-radius"><label for="group-radius">Group photos within</label><select id="group-radius"><option value="50" ${draft.radius===50?'selected':''}>50 meters</option><option value="150" ${draft.radius===150?'selected':''}>150 meters</option><option value="500" ${draft.radius===500?'selected':''}>500 meters</option></select></div>${unplaced.length?`<section class="unplaced-section glass"><div class="section-heading"><div><h2>One little <em>missing piece.</em></h2><p>These photos have no location. Add a place, or keep them in your album.</p></div>${icon('pin')}</div><div class="unplaced-grid">${unplaced.map(p=>`<button class="unplaced-card" data-action="locate" data-id="${p.id}"><img src="${p.src}" alt="${esc(p.caption)}"><span>＋ Add location</span></button>`).join('')}</div></section>`:''}<div class="composer-stops">${groups.map((s,i)=>`<section class="composer-stop glass"><header><span class="stop-index">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(s.name)}</h2><p>${date(s.takenAt)} · ${count(s.photos.length,'photo')}</p></div><div class="stop-order"><button data-action="move-stop" data-id="${s.id}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${esc(s.name)} earlier">↑</button><button data-action="move-stop" data-id="${s.id}" data-direction="1" ${i===groups.length-1?'disabled':''} aria-label="Move ${esc(s.name)} later">↓</button></div></header><div class="group-thumbs">${s.photos.map(p=>`<button data-action="locate" data-id="${p.id}" aria-label="Change location for ${esc(p.caption)}"><img src="${p.src}" alt="${esc(p.caption)}"></button>`).join('')}</div><button class="stop-memory-editor" data-action="draft-note" data-id="${s.id}">${icon(s.notes.length?'note':'plus')}<span>${s.notes.length?esc(s.notes[0]):'What made this place special?'}${s.highlight?`<small>✧ ${esc(s.highlight)}</small>`:''}</span>${icon('edit')}</button></section>`).join('')}</div>`,`<button class="text-link" data-action="create-back">${icon('back')}Photos</button><button class="button dark" data-action="create-next">Make it yours ${icon('arrow')}</button>`);$('#group-radius').onchange=e=>{draft.radius=Number(e.target.value);composerPlaces()};}
function audienceName(value){return {private:'Only me',followers:'Followers',everyone:'Everyone'}[value]||'Only me';}
function publishJourney(){if(!draft?.photos.length||!draft.title?.trim()||!draft.place?.trim()||!draft.start||!draft.end||draft.end<draft.start){toast('Add a title, destination, and valid dates before posting.');createStory();return}const posted={...structuredClone(draft),author:'me',createdAt:new Date().toISOString()};journeys.unshift(posted);draft=null;editingDraft=false;createStep=1;persist();go('journey',posted.id);modal('Your journey is ready',`<div class="post-success"><span class="success-orbit">${icon('check')}</span><span class="eyebrow">EVERY MOMENT, CONNECTED</span><h2>A little piece<br>of <em>your world.</em></h2><img src="${coverPhoto(posted).src}" alt="Your journey cover"><h3>${esc(posted.title)}</h3><p>${count(getStops(posted).length,'stop')} · ${count(posted.photos.length,'photo')} · ${audienceName(posted.audience)}</p><small>Saved on this device. This preview doesn’t publish online.</small></div>`,`<button class="text-link" data-action="nav" data-id="profile">Your profile</button><button class="button dark" data-action="close-editor">View journey ${icon('arrow')}</button>`);}
async function initApp(){try{const data=await readState();if(data?.version===1){journeys=data.journeys||[];sampleState=data.sampleState||sampleState;draft=data.draft||null;createStep=data.createStep||1;profile={...profile,...data.profile};savedIds=new Set(data.savedIds||[]);likedIds=new Set(data.likedIds||[]);following=new Set(data.following||[]);comments=data.comments||{};}}catch{storageWarned=true;}sampleState.author='me';sampleState.category='Coast';sampleState.audience||='private';window.addEventListener('hashchange',()=>{closeEditor();renderScreen();window.scrollTo(0,0)});window.addEventListener('popstate',()=>{closeEditor();renderScreen();window.scrollTo(0,0)});renderScreen();}

document.addEventListener('click',async e=>{const v=e.target.closest('[data-view]');if(v){changeView(v.dataset.view);return}const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action,id=el.dataset.id;
 if(a==='nav'){if(id==='explore'){searchQuery='';exploreCategory='All'}if(id==='profile')profileTab='journeys';go(id);}
 if(a==='return-feed')go(returnScreen==='create'?'home':returnScreen||'home');
 if(a==='author'){profileTab='journeys';go('profile',id);}
 if(a==='feed-tab'){feedTab=id;renderHome();}
 if(a==='feed-category'){feedCategory=id;renderHome();}
 if(a==='explore-category'){exploreCategory=id;renderExplore();}
 if(a==='search-destination'){searchQuery=id;exploreCategory='All';go('explore');}
 if(a==='toggle-save'){if(savedIds.has(id))savedIds.delete(id);else savedIds.add(id);persist();renderScreen();toast(savedIds.has(id)?'Kept on your someday shelf.':'Journey removed from Saved.');}
 if(a==='like'){if(likedIds.has(id))likedIds.delete(id);else likedIds.add(id);persist();el.classList.toggle('liked',likedIds.has(id));el.setAttribute('aria-pressed',likedIds.has(id));el.setAttribute('aria-label',`${likedIds.has(id)?'Unlike':'Like'} ${findJourney(id).title}`);el.innerHTML=icon('heart')+`<span>${likedIds.has(id)?'Loved':'Love this'}</span>`;}
 if(a==='comments')showComments(id);
 if(a==='follow'){if(following.has(id))following.delete(id);else following.add(id);persist();if($('#editor').open)showFollowing();else renderScreen();toast(following.has(id)?`Following ${person(id).name}.`:`Unfollowed ${person(id).name}.`);}
 if(a==='profile-tab'){profileTab=id;renderProfile(el.dataset.person||'me');}
 if(a==='profile-photo'){go('journey',el.dataset.journey);openPhoto(id);}
 if(a==='edit-profile')editProfile();
 if(a==='following-list')showFollowing();
 if(a==='settings')modal('Your settings',`<span class="eyebrow">YOUR WORLD, YOUR WAY</span><h2>A little <em>housekeeping.</em></h2><div class="settings-row">${icon('person')}<div><strong>Your profile</strong><p>Your name, bio, and home base.</p></div><button class="button glass" data-action="edit-profile">Edit</button></div><div class="settings-row">${icon('lock')}<div><strong>Saved on this device</strong><p>Your journeys, drafts, bookmarks, and profile are stored in this browser. This prototype has no account or cloud sync.</p></div></div><div class="settings-row">${icon('globe')}<div><strong>Sharing is a preview</strong><p>No posts, photos, follows, or comments are sent to other users.</p></div></div>`,`<span class="muted">Atlas · Design preview</span><button class="button dark" data-action="close-editor">Done</button>`);
 if(a==='use-demo'){samplePhotos.forEach(p=>{if(!draft.photos.some(d=>d.id===p.id)){draft.photos.push(structuredClone(p));if(sampleAnnotations[p.id])draft.annotations[p.id]=structuredClone(sampleAnnotations[p.id]);}});draft.cover||='p2';draft.place||='Amalfi Coast, Italy';draft.title||='A little closer to la dolce vita.';draft.caption||=sampleJourney.caption;renderCreatePhotos();toast('Sample photos added. Try grouping places and adding a memory.');}
 if(a==='remove-draft-photo'){draft.photos=draft.photos.filter(p=>p.id!==id);delete draft.annotations[id];if(draft.cover===id)draft.cover=draft.photos[0]?.id||null;renderCreatePhotos();}
 if(a==='save-draft'){collectStory();await flushState();profileTab='drafts';go('profile');toast('Your draft is ready whenever you are.');}
 if(a==='review-places'){createStep=2;composerPlaces();window.scrollTo(0,0);}
 if(a==='move-stop'){const groups=getStops(draft),from=groups.findIndex(s=>s.id===id),to=from+Number(el.dataset.direction);if(from>=0&&to>=0&&to<groups.length){[groups[from],groups[to]]=[groups[to],groups[from]];draft.stopOrder=groups.map(s=>s.id);composerPlaces();}}
 if(a==='stop')openStop(id);
 if(a==='close-stop')$('#stop-sheet').close();
 if(a==='close-editor')closeEditor();
 if(a==='close-lightbox')$('#lightbox').close();
 if(a==='collection')showCollection();
 if(a==='saved')showCollection(true);
 if(a==='save'){if(savedIds.has(journey.id))savedIds.delete(journey.id);else savedIds.add(journey.id);render();toast(savedIds.has(journey.id)?'Journey saved':'Journey removed from saved');}
 if(a==='share')share();
 if(a==='gallery')showGallery();
 if(a==='organize'&&ownJourney()){editingDraft=false;organize(false);}
 if(a==='organize-draft'){editingDraft=true;createStep=2;organize(true);}
 if(a==='done-organize'){closeEditor();render();}
 if(a==='edit-note'&&ownJourney())openNote(id,false);
 if(a==='draft-note')openNote(id,true);
 if(a==='locate'){editingDraft=screen==='create';if(editingDraft||ownJourney())openLocation(id);}
 if(a==='choose-place'){const s=getStops(activeJourney()).find(s=>s.id===id);if(s){chooseLocation(s.gps,s.name);$$('.location-choices button').forEach(b=>b.classList.toggle('chosen',b===el));}}
 if(a==='show-on-map'){$('#stop-sheet').close();selectedId=id;render();$('.journey-canvas').scrollIntoView({block:'center',behavior:'smooth'});}
 if(a==='canvas-fit')$('.journey-canvas').scrollIntoView({block:'center',behavior:'smooth'});
 if(a==='zoom-in')map?.zoomIn();if(a==='zoom-out')map?.zoomOut();if(a==='fit-map')fitMap();
 if(a==='map-notes'){showMapNotes=!showMapNotes;el.innerHTML=icon('note')+'Notes '+(showMapNotes?'on':'off');el.setAttribute('aria-pressed',showMapNotes);renderMapMarkers();}
 if(a==='photo')openPhoto(id);
 if(a==='photo-prev'&&lightboxIndex>0){lightboxIndex--;renderLightbox();}
 if(a==='photo-next'&&lightboxIndex<lightboxIds.length-1){lightboxIndex++;renderLightbox();}
 if(a==='photo-location'&&ownJourney()){$('#lightbox').close();$('#stop-sheet').close();editingDraft=false;openLocation(id);}
 if(a==='add-to-stop'&&ownJourney()){const s=stops.find(s=>s.id===id);editingDraft=false;modal('Add photos to stop',`<h2>More of <em>${esc(s.name)}.</em></h2><p class="modal-description">Photos without GPS tags will be placed here. Photos with GPS tags keep their own location.</p>${uploadMarkup()}`);bindUpload(s);}
 if(a==='create')go('create');
 if(a==='pick-sample'){const at=draft.photos.findIndex(p=>p.id===id);if(at>=0){draft.photos.splice(at,1);delete draft.annotations[id];if(draft.cover===id)draft.cover=draft.photos[0]?.id||null}else{draft.photos.push(structuredClone(samplePhotos.find(p=>p.id===id)));if(sampleAnnotations[id])draft.annotations[id]=structuredClone(sampleAnnotations[id]);draft.cover||=id;}renderCreatePhotos();}
 if(a==='create-next')nextCreate();
 if(a==='create-back'){if(createStep===4)createStory();else if(createStep===3){collectStory();createStep=2;organize(true);}else renderCreatePhotos();}
 if(a==='choose-cover'){draft.cover=id;$$('.cover-select button').forEach(b=>{b.classList.toggle('chosen',b===el);b.setAttribute('aria-pressed',b===el)});const img=$('#chosen-cover-preview');if(img)img.src=coverPhoto(draft).src;persist();}
 if(a==='post')publishJourney();
 if(a==='open-journey')go('journey',id);
 if(a==='profile')go('profile');
 if(a==='copy-link'){try{await navigator.clipboard.writeText(location.origin+location.pathname+'#/journey/'+encodeURIComponent(journey.id));toast('Preview link copied');closeEditor();}catch{toast('Copy this page’s address from the browser.');}}
});
for(const d of $$('dialog')){d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d.id==='editor')closeEditor();else d.close();}});}
$('#editor').addEventListener('cancel',()=>{if(editingDraft&&$('#story-form'))collectStory();persist();editingDraft=false;});
let lastMobile=window.matchMedia('(max-width:700px)').matches;window.addEventListener('resize',()=>{const mobile=window.matchMedia('(max-width:700px)').matches;if(mobile!==lastMobile){lastMobile=mobile;const scene=$('#route-scene');if(scene)scene.innerHTML=journeyCanvas();}locationMap?.invalidateSize();});
initApp();
if(document.modelContext?.registerTool){const ctrl=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:ctrl.signal})).catch(()=>{})}catch{}};register({name:'open_journey_stop',title:'Open a stop’s photos and notes',description:'Open the selected journey stop in a bottom sheet.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!Number.isInteger(input.index)||!stops[input.index])throw Error('Choose an existing stop.');openStop(stops[input.index].id);return {name:stops[input.index].name,photos:stops[input.index].photos.length,notes:stops[input.index].notes}}});register({name:'open_photo_organizer',title:'Organize journey photos',description:'Show photos grouped by location and photos that need a location. This does not upload or post anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){organize(false);return {stops:stops.length,unplaced:journey.photos.filter(p=>!validGPS(p.gps)).length}}});window.addEventListener('pagehide',()=>ctrl.abort(),{once:true});}
